package com.gathin.tvhome;
import android.app.*;import android.os.*;import android.text.InputType;import android.view.View;import android.widget.*;
/** Hotspot controls use the real saved SoftAP configuration and native tethering request. */
final class SessionNetworkUi {
 static void power(Activity a,Runnable refresh){if(!SessionSettingsUi.ready(a))return;SessionSettingsUi.read(a,SettingsSessionClient.HOTSPOT_READ,new Bundle(),state->{boolean on=state.getInt("state")==13;final int[] selected={on?1:0};AlertDialog d=new SettingsPopup.Builder(a).setTitle("Hotspot").setSingleChoiceItems(new String[]{"Off","On"},selected[0],(dialog,w)->selected[0]=w).setPositiveButton("Apply",(dialog,w)->{if((selected[0]==1)==on)return;Bundle input=new Bundle();input.putBoolean("on",selected[0]==1);SessionSettingsUi.confirm(a,selected[0]==1?"Start hotspot?":"Stop hotspot?","Sharing can interrupt Wi-Fi and the computer connection. Keep a way to reach the stock network controls if the helper disconnects.",()->SessionSettingsUi.change(a,SettingsSessionClient.HOTSPOT_POWER,input,refresh));}).setNegativeButton("Cancel",null).create();d.show();SettingsPopup.style(d);});}
 private static TextView label(Activity a,String text){TextView v=new TextView(a);v.setText(text);v.setTextSize(17);v.setTextColor(0xffd5dbe2);v.setPadding(0,14,0,4);v.setTypeface(UiFont.get(a,R.string.font_regular));return v;}
 static void config(Activity a,String focus,Runnable refresh){if(!SessionSettingsUi.ready(a))return;SessionSettingsUi.read(a,SettingsSessionClient.HOTSPOT_READ,new Bundle(),before->{
  int mode=before.getInt("security"),oldBand=before.getInt("band");if(mode!=0&&mode!=1){Toast.makeText(a,"This hotspot security mode is not supported by this editor.",Toast.LENGTH_LONG).show();return;}
  LinearLayout box=new LinearLayout(a);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(32,12,32,12);
  EditText name=new EditText(a),password=new EditText(a);name.setSingleLine(true);name.setText(before.getString("name"));password.setSingleLine(true);password.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);password.setText(before.getString("password"));name.setTextColor(0xfff5f5fa);password.setTextColor(0xfff5f5fa);
  Spinner security=new Spinner(a),band=new Spinner(a);security.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,new String[]{"None","WPA2-PSK"}));security.setSelection(mode);
  int[] bands={1,2,3};band.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,new String[]{"2.4 GHz","5 GHz","Automatic"}));for(int i=0;i<bands.length;i++)if(bands[i]==oldBand)band.setSelection(i);
  CheckBox show=new CheckBox(a);show.setText("Display password");show.setTextColor(0xfff5f5fa);show.setOnCheckedChangeListener((button,on)->password.setInputType(InputType.TYPE_CLASS_TEXT|(on?InputType.TYPE_TEXT_VARIATION_VISIBLE_PASSWORD:InputType.TYPE_TEXT_VARIATION_PASSWORD)));
  box.addView(label(a,"Network SSID"));box.addView(name);box.addView(label(a,"Password"));box.addView(password);box.addView(show);box.addView(label(a,"Security"));box.addView(security);box.addView(label(a,"AP frequency band"));box.addView(band);
  ScrollView scroll=new ScrollView(a);scroll.addView(box);AlertDialog d=new SettingsPopup.Builder(a).setTitle("Hotspot settings").setView(scroll).setPositiveButton("Apply",null).setNegativeButton("Cancel",null).create();d.show();SettingsPopup.style(d);
  if("Password".equals(focus))password.requestFocus();else if("Security".equals(focus))security.requestFocus();else if("Select AP frequency band".equals(focus))band.requestFocus();else name.requestFocus();
  d.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{try{String ssid=name.getText().toString(),pass=password.getText().toString();int type=security.getSelectedItemPosition();SettingsSessionPolicy.network(ssid,pass,type!=0);Bundle input=new Bundle();input.putParcelable("config",before.getParcelable("config"));input.putString("name",ssid);input.putString("password",pass);input.putInt("security",type);input.putInt("band",bands[band.getSelectedItemPosition()]);d.dismiss();SessionSettingsUi.confirm(a,"Save hotspot settings?","Connected clients may be disconnected.",()->SessionSettingsUi.change(a,SettingsSessionClient.HOTSPOT_SET,input,refresh));}catch(IllegalArgumentException invalid){name.setError(invalid.getMessage());}});
 });}
 private SessionNetworkUi(){}
}
